mapper.select:
SELECT id, source, title, summary, content, external_url AS externalUrl, image_url AS imageUrl, is_visible AS isVisible, is_pinned AS isPinned, published_at AS publishedAt, created_at AS createdAt, updated_at AS updatedAt FROM site_notices
source = #{source}
AND is_visible = #{isVisible}
AND is_pinned = #{isPinned}
ORDER BY is_pinned DESC, published_at DESC, id DESC

